  {"id": "Restaurant_376490000A_000411", "name": "聖林溫州大餛飩", "lat": 23.56908645, "lon": 120.30530636, "address": "雲林縣北港鎮仁和路22號", "description": "聖林溫州大餛飩以大份量餛飩和有口皆碑的牛奶蓮子湯聞名，是北港隱藏美食。", "hours": "11:00-14:00 17:00-20:00 周一公休", "image": "https://k241.noon360.com/public/upload/StoreCover/241220052945517047AEJAG.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000412", "name": "宛津手工麵", "lat": 23.69480524, "lon": 120.31149083, "address": "雲林縣褒忠鄉中正路230號", "description": "「宛津手工麵」的手工麵條Q彈有勁，搭配自製辣椒醬香辣開胃，麻醬麵、肉圓、米糕值得一試。價格實惠，份量足，是在地人推薦的美味小店，營業至下午1:30，記得早點去！", "hours": "06:30-13:30(週一休)", "image": "https://k241.noon360.com/public/upload/StoreCover/250704022817257882RQHNR.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000413", "name": "泉威布丁豆花", "lat": 23.69773132, "lon": 120.30937859, "address": "雲林縣褒忠鄉中勝路59之9號", "description": "當地人推薦的甜品店——泉威布丁豆花。主打三色豆花，包含原味、濃雞蛋香及巧克力口味，口感滑順有層次。特別的是，它用飲料杯盛裝，搭配粗吸管，走到哪吃到哪，方便又好吃，是消暑解饞的好選擇！", "hours": "09:00-20:00(週日休)", "image": "https://k241.noon360.com/public/upload/StoreCover/2507040231498610755SPN3.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000414", "name": "褒忠阿桂竹仔腳碗粿", "lat": 23.69599001, "lon": 120.30949021, "address": "雲林縣褒忠鄉中勝路19號", "description": "褒忠的「阿桂竹仔腳碗粿」開業超過60年，是在地人心中的老店。它的碗粿口感滑順、醬香濃郁，與南部的濕軟型不同，肉塊有嚼勁。推薦試試「加蛋碗粿」，口感更豐富。此外，這裡的綜合湯也很實惠，料多實在，暖胃又美味。", "hours": "14:00-18:00", "image": "https://k241.noon360.com/public/upload/StoreCover/250704023610599820KEDEA.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000415", "name": "和香珍囍餅（百年老店）", "lat": 23.69482361, "lon": 120.31186066, "address": "雲林縣褒忠鄉中正路153號", "description": "來到褒忠別錯過百年老店「和香珍囍餅」！在地人從小吃到大，傳統喜餅、大餅經典不敗，還有適合遊客的小份甜點。推薦必吃「蒜頭酥」蒜香撲鼻、綿密酥口，「牛舌餅」酥香誘人，是送禮或伴手禮的好選擇！", "hours": "07:30-22:00", "image": "https://k241.noon360.com/public/upload/StoreCover/250704024718569844BKKRL.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000416", "name": "阿拉丁現榨果汁屋", "lat": 23.7002831, "lon": 120.19880152, "address": "雲林縣台西鄉民族路6號", "description": "台西夏日消暑必備，一定要來一杯「阿拉丁現榨果汁」！嚴選當季水果現打，無添加、果香濃郁，綜合果汁粉嫩滑順、自然香甜。邊喝邊吹海風，感受專屬海線的療癒夏日儀式。", "hours": "09:00-20:00(週一休)", "image": "https://k241.noon360.com/public/upload/StoreCover/2507040306262401304RX3T.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000417", "name": "巴比鹹酥雞", "lat": 23.67424426, "lon": 120.38955679, "address": "雲林縣土庫鎮中山路48號", "description": "店內以大色塊與亮瓷地磚打造文青風，招牌鹽酥雞與炸物香酥不膩，成為小鎮宵夜靈魂", "hours": "17:00-21:30(週日、一休)", "image": "https://k241.noon360.com/public/upload/StoreCover/250924053715929509RJ4YV.jpg", "categories": []},
  {"id": "Restaurant_376490000A_000418", "name": "TGC台灣咖啡莊園", "lat": 23.64244, "lon": 120.59187369, "address": "雲林縣古坑鄉大埔66號", "description": "最純正的台灣咖啡，日治時期引進阿拉比卡種咖啡豆，擄獲當時日本天皇的心，得『御用咖啡』之美名。", "hours": "08:00-17:00 無公休日", "image": "https://k241.noon360.com/public/upload/StoreCover/220930041350714904BARRY.jpg", "categories": ["cafe"]},
  {"id": "Restaurant_376490000A_000419", "name": "Mishka Coffee Antique 米嘻咖咖啡古董傢俱", "lat": 23.70749, "lon": 120.44282, "address": "雲林縣虎尾鎮光明路111號", "description": "精品古董與蛋糕，值得體驗的華貴！華奢貴氣不瞭亂的古董陳設，讓整間店彷彿錯身於老闆來自的愛沙尼亞。以古董西洋家具為主，並有著許多小物，一趟可體驗的貴族空間感，值得浪費無數日子在這享受下午茶。", "hours": "13:30-19:00一二公休", "image": "https://k241.noon360.com/public/upload/StoreCover/230210041206592310WE4MZ.jpg", "categories": ["cafe"]},
  {"id": "Restaurant_376490000A_000420", "name": "尚豆咖啡", "lat": 23.67149021, "lon": 120.48322936, "address": "雲林縣斗南鎮新生三路128號", "description": "尚豆咖啡 x Plus Minus-，專注於咖啡的本質，成為您需要咖啡因的好朋友！", "hours": "10:00-18:00 無公休日", "image": "https://k241.noon360.com/public/upload/StoreCover/221002110723606016265W4.jpg", "categories": ["cafe"]},
  {"id": "Restaurant_376490000A_000421", "name": "一品香火鍋", "lat": 23.71356, "lon": 120.54334, "address": "雲林縣斗六市武昌路182號", "description": "火鍋是台灣人喜愛的美食，大街小巷、鄉村都市皆可以看到火鍋店的蹤跡，可見台灣人對於「火鍋」的熱愛程度有多高，早、中、晚都要來一下火鍋。 本店無收「共鍋費、服務費」，提供甜美的冰淇淋與解渴的飲料，湯頭多樣性選擇，搭配著新鮮蔬果菜盤，加上一碗熱…", "hours": "周一 ~ 周四 上午11:00至晚上11:00 周五 ~ 周日 上午11:00至晚上12:00", "image": "https://k241.noon360.com/public/upload/StoreCover/2206100423254148117RUVW.jpeg", "categories": []},
  {"id": "Restaurant_376490000A_000422", "name": "肉燕", "lat": 23.6731534, "lon": 120.3886886, "address": "雲林縣土庫鎮三民街17號", "description": "以肉為皮，再包肉做的餃子型點心！這民國６０年開至今的美味，仰賴老闆手路活，將豬後腿拍至起筋性，摻以薄粉輾成紙薄燕皮，才包入肉餡，口感輕盈滑香。考驗煮、包功夫，這樣的精緻口味如此不易，值得一試！", "hours": "11:00-19:00一公休", "image": "https://k241.noon360.com/public/upload/StoreCover/230210035254704466L3ABY.png", "categories": []},
  {"id": "Restaurant_376490000A_000423", "name": "正宗青草茶", "lat": 23.5717075, "lon": 120.2417468, "address": "雲林縣水林鄉水林路343號", "description": "自產自銷，台灣有機古法草本味以友善農法自耕的甘蔗，配上自家耕種草本植物，讓店內甘蔗汁、青草茶，變做不分節令的熱門商品，老闆也嚴選屏東檸檬調配清香甘蔗檸檬汁，想品嚐台灣草本清香味，首推這間！", "hours": "08:00-20:00", "image": "https://k241.noon360.com/public/upload/StoreCover/2302100403332876923CTZS.jpg", "categories": []}
